INSERT INTO `contact_us` (`IdContact`, `FullName`, `Email`, `Subject`, `Message`, `PhoneNumber`, `Date_creation`, `Location`, `ip_address`, `user_agent`, `is_readed`) VALUES
(13, 'IRAKOZE Yvette', 'yvette.irakoze2008@gmail.com', 'Hypertrophie de la tyrhoide', 'Bjr Dr, jBonjour Dr. J’ai un problème d’hypertrophie de la thyroïde. J’ai 48 ans et je mesure 1,62m et je pèse 74 Kg. J’ai été diagnostiqué de cette maladie il y a 2ans et depuis lors les problèmes ne cessent de peser sur ma santé. Mal de tête incessante, nervosité incontrôlé, crise d’humeurs, fatigues généralisée etc…\nJe viens donc vers vous pour voir s’il n’y a pas d’alternative pour parier à tous ces problèmes car un médecin ORL m’a dit que la solution à envisager est l’ablation de la thyroïde, ce qui me parait désastreux pour ma santé. Merci pour votre reponse', '+25761855762', '2026-05-20 14:22:55', 'Bujumbura- Kinama, Quartier BUKIRASAZI', '143.105.213.90', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64; rv:150.0) Gecko/20100101 Firefox/150.0', 0),
(14, 'Irakoze Yvette', 'jcndayisaba2018@gmail.com', 'Hyprhypertrophie tyrhoïde', 'J\'ai été diagnostiqué de l\'hypertrophie de la thyroïde et le médecin m\'a dit qu\'il faut de la chirurgie. Mais je pense qu\'avant cela, il faut voir s\'il n\'y a pas d\'autres alternatives. C\'est pourquoi je viens vers vous. Que ce que vous proposez comme solution? J\'ai 48 ans, je pèse 72 Kg et je mesure 1,6 m. Merci pour votre réponse.', '+25779930821', '2026-05-21 06:42:02', 'Burundi', '143.105.213.207', 'Mozilla/5.0 (Linux; Android 10; K) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/148.0.0.0 Mobile Safari/537.36', 1),
(15, 'NDUWAYESU BELYSE', 'admin@vip-school.com', 'bujumbura', 'jhjhhhhhhhhhhhhhhhhhhhhhhhhhhhhhhhhhhhhhh', '257 79 66 64', '2026-08-04 01:29:38', 'bujumbura', '::1', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/150.0.0.0 Safari/537.36', 1);
INSERT INTO `faq` (`id_faq`, `question`, `reponse`, `categorie`, `ordre`, `est_publiee`, `id_page_associee`) VALUES
(1, 'What is NUFOTEC?', 'NUFOTEC BURUNDI is a Burundian agro-industrial biotechnology enterprise engaged in commercial organic farming and manufacturing of standardized plant-based health products.', 'general', 1, 1, NULL),
(2, 'What products do you manufacture?', 'We manufacture 7 categories of products: TCAMs, Nutraceuticals, Clean-label fortified foods, Organic fertilizers, Phytomedicines, and Phytopharmaceuticals.', 'produits', 2, 1, NULL),
(3, 'Are your products GMP compliant?', 'Yes, all our products are manufactured in our GMP-compliant facility NUFOTEC PHYTOMED INDUSTRIES.', 'qualite', 3, 1, NULL),
(4, 'How can I invest in NUFOTEC?', 'You can submit a Manifestation of Interest (MOI) through our website or contact our investor relations team.', 'investissement', 4, 1, NULL),
(5, 'Do you work with out-growers?', 'Yes, we have structured out-grower networks and plan to integrate 5,000+ out-growers by 2031, with focus on youth and women participation.', 'social', 5, 1, NULL),
(6, 'What certifications do you have?', 'We have multiple certifications including RDB registration, Investment License, and we are in process for ISO and GMP certifications.', 'qualite', 6, 1, NULL);
